import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { GoogleGenAI } from '@google/genai';
import OpenAI from 'openai';
import Anthropic from '@anthropic-ai/sdk';

export type AIProviderType = 'openai' | 'gemini' | 'groq' | 'anthropic';

export interface AIMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface AIOptions {
  temperature?: number;
  maxTokens?: number;
  responseFormat?: 'text' | 'json_object';
}

export interface AIProviderStrategy {
  generateCompletion(messages: AIMessage[], options?: AIOptions): Promise<string>;
}

export class OpenAIStrategy implements AIProviderStrategy {
  private client: OpenAI;
  private model: string;

  constructor(apiKey: string, model: string = 'gpt-4o') {
    this.client = new OpenAI({ apiKey });
    this.model = model;
  }

  async generateCompletion(messages: AIMessage[], options?: AIOptions): Promise<string> {
    const response = await this.client.chat.completions.create({
      model: this.model,
      messages: messages.map(m => ({ role: m.role, content: m.content })),
      temperature: options?.temperature ?? 0.7,
      max_tokens: options?.maxTokens,
      response_format: options?.responseFormat === 'json_object' ? { type: 'json_object' } : undefined,
    });
    return response.choices[0]?.message?.content ?? '';
  }
}

export class GeminiStrategy implements AIProviderStrategy {
  private client: GoogleGenAI;
  private model: string;

  constructor(apiKey: string, model: string = 'gemini-2.5-flash') {
    this.client = new GoogleGenAI({ apiKey });
    this.model = model;
  }

  async generateCompletion(messages: AIMessage[], options?: AIOptions): Promise<string> {
    const systemInstruction = messages.find(m => m.role === 'system')?.content;
    const chatHistory = messages.filter(m => m.role !== 'system');

    const contents = chatHistory.map(m => ({
      role: m.role === 'assistant' ? 'model' : 'user',
      parts: [{ text: m.content }],
    }));

    const response = await this.client.models.generateContent({
      model: this.model,
      contents,
      config: {
        systemInstruction,
        temperature: options?.temperature ?? 0.7,
        maxOutputTokens: options?.maxTokens,
        responseMimeType: options?.responseFormat === 'json_object' ? 'application/json' : 'text/plain',
      },
    });

    return response.text ?? '';
  }
}

export class AIProviderRouter {
  private strategies: Map<AIProviderType, AIProviderStrategy> = new Map();
  private defaultProvider: AIProviderType;

  constructor(defaultProvider: AIProviderType = 'gemini') {
    this.defaultProvider = defaultProvider;
  }

  public registerProvider(type: AIProviderType, strategy: AIProviderStrategy) {
    this.strategies.set(type, strategy);
  }

  public async execute(messages: AIMessage[], options?: AIOptions, preferredProvider?: AIProviderType): Promise<string> {
    const providerKey = preferredProvider || this.defaultProvider;
    const strategy = this.strategies.get(providerKey);

    if (!strategy) {
      throw new Error(`AI Provider strategy for [${providerKey}] is not registered.`);
    }

    try {
      return await strategy.generateCompletion(messages, options);
    } catch (error) {
      console.error(`Provider ${providerKey} failed:`, error);
      // Fallback loop if needed across available registered providers
      for (const [type, fallbackStrategy] of this.strategies.entries()) {
        if (type !== providerKey) {
          try {
            console.warn(`Attempting fallback to provider: ${type}`);
            return await fallbackStrategy.generateCompletion(messages, options);
          } catch (fallbackError) {
            console.error(`Fallback provider ${type} also failed.`);
          }
        }
      }
      throw error;
    }
  }
}

import { PrismaClient } from '@prisma/client';
import { AIProviderRouter } from './AIProviderRouter';

export interface DocumentChunkMetadata {
  chunkId: string;
  documentId: string;
  content: string;
  pageNumber?: number;
  similarity?: number;
}

export class VectorSearchRagService {
  private prisma: PrismaClient;
  private aiRouter: AIProviderRouter;

  constructor(prisma: PrismaClient, aiRouter: AIProviderRouter) {
    this.prisma = prisma;
    this.aiRouter = aiRouter;
  }

  private async generateEmbedding(text: string): Promise<number[]> {
    // In production, invoke text-embedding-3-small or text-embedding-004
    // Returning a dummy 1536-dimensional vector for compilation completeness
    const embeddingText = text.replace(/\n/g, ' ');
    // Mock implementation of embedding API call
    return new Array(1536).fill(0.01);
  }

  public async indexDocumentChunk(documentId: string, content: string, pageNumber?: number): Promise<string> {
    const vector = await this.generateEmbedding(content);
    const vectorString = `[${vector.join(',')}]`;

    const result = await this.prisma.$executeRaw`
      INSERT INTO "DocumentChunk" (id, "documentId", content, "pageNumber", embedding)
      VALUES (gen_random_uuid(), ${documentId}, ${content}, ${pageNumber || null}, ${vectorString}::vector)
      RETURNING id;
    `;

    return result;
  }

  public async retrieveRelevantContext(userId: string, query: string, topK: number = 5): Promise<DocumentChunkMetadata[]> {
    const queryVector = await this.generateEmbedding(query);
    const vectorString = `[${queryVector.join(',')}]`;

    // Execute raw pgvector cosine distance query (<=> operator)
    const chunks = await this.prisma.$queryRaw<Array<DocumentChunkMetadata & { similarity: number }>>`
      SELECT 
        dc.id as "chunkId",
        dc."documentId",
        dc.content,
        dc."pageNumber",
        1 - (dc.embedding <=> ${vectorString}::vector) as similarity
      FROM "DocumentChunk" dc
      JOIN "Document" d ON dc."documentId" = d.id
      WHERE d."userId" = ${userId}
      ORDER BY dc.embedding <=> ${vectorString}::vector ASC
      LIMIT ${topK};
    `;

    return chunks;
  }

  public async answerWithContext(userId: string, query: string, difficultyLevel: 'beginner' | 'intermediate' | 'advanced'): Promise<string> {
    const relevantChunks = await this.retrieveRelevantContext(userId, query, 4);

    const contextText = relevantChunks
      .map((c, i) => `[Source ${i + 1} (Page ${c.pageNumber || 'N/A'}]:\n${c.content}`)
      .join('\n\n');

    const systemPrompt = `You are Aegis, an expert AI Personal Study Assistant.
Answer the student's question using ONLY the provided study material context.
Adjust your explanation style to a '${difficultyLevel}' difficulty level.
If the answer cannot be found in the context, clearly state that you couldn't find it in the uploaded notes.

Context:
${contextText}`;

    const response = await this.aiRouter.execute([
      { role: 'system', content: systemPrompt },
      { role: 'user', content: query }
    ], { temperature: 0.3 });

    return response;
  }
}
